SELECT

FROM member_package
WHERE member_id = #{memberId}
  AND package_type = #{packageType}
  AND status = 1
  AND locked_order_id IS NULL
  AND effective_from <= #{now}
  AND expire_time > #{now}


        AND remaining_kwh > 0


        AND remaining_minutes > 0


        AND remaining_times > 0


ORDER BY expire_time, id

mapper.update:
UPDATE member_package
SET locked_order_id = #{orderId},
    update_time = #{updateTime}
WHERE id = #{id}
  AND locked_order_id IS NULL
  AND status = 1

UPDATE member_package
SET locked_order_id = NULL,
    update_time = #{updateTime}
WHERE id = #{id}
  AND locked_order_id = #{orderId}

UPDATE member_package
SET locked_order_id = NULL,
    update_time = #{updateTime}
WHERE locked_order_id = #{orderId}

UPDATE member_package
SET status = CASE WHEN remaining_kwh <= #{usedKwh} THEN 2 ELSE status END,
    remaining_kwh = remaining_kwh - #{usedKwh},
    locked_order_id = NULL,
    update_time = #{updateTime}
WHERE id = #{id}
  AND locked_order_id = #{orderId}

UPDATE member_package
SET status = CASE WHEN remaining_minutes <= #{usedMinutes} THEN 2 ELSE status END,
    remaining_minutes = remaining_minutes - #{usedMinutes},
    locked_order_id = NULL,
    update_time = #{updateTime}
WHERE id = #{id}
  AND locked_order_id = #{orderId}

UPDATE member_package
SET status = CASE WHEN remaining_times <= 1 THEN 2 ELSE status END,
    remaining_times = remaining_times - 1,
    locked_order_id = NULL,
    update_time = #{updateTime}
WHERE id = #{id}
  AND locked_order_id = #{orderId}

UPDATE member_package
SET status = 3,
    update_time = #{updateTime}
WHERE status = 1
  AND locked_order_id IS NULL
  AND expire_time <= #{now}
LIMIT #{limit}
